#include "integer.h"
#include <limits.h>
static uint64_t even_div(uint64_t a,uint64_t b){uint64_t q=a/b,r=a%b;return q+(r>b-r||(r==b-r&&(q&1)));}
int int_linear(IRuntime *r,int id,int16_t *out,IScale *os,const int16_t *x,IScale xs,int logits){const ITensor *w=&r->model->linear[id];IFixed sx=if_scale(xs);for(unsigned row=0;row<w->rows;row++){const int8_t *p=w->w+(size_t)row*w->cols;int64_t acc=0;for(unsigned i=0;i<w->cols;i++)acc+=(int64_t)p[i]*x[i];r->work[row]=if_mul(if_mul(if_make(acc,0),sx),if_scale(w->scales[row]));}if(logits)int_pack32(r->logits,&r->ls,r->work,w->rows,&r->stats);else int_pack16(out,os,r->work,w->rows,&r->stats);return 0;}
void int_norm(IRuntime *r,int16_t *out,IScale *os,const int16_t *x,IScale xs,const ITensor *gamma,unsigned n){uint64_t sum=0;for(unsigned i=0;i<n;i++)sum+=(uint64_t)((int64_t)x[i]*x[i]);IFixed sx=if_scale(xs);IFixed variance=if_div(if_mul(if_make((int64_t)sum,0),if_mul(sx,sx)),if_make(n,0));IFixed denom=if_sqrt(if_add(variance,if_scale(r->model->epsilon)));IFixed factor=if_div(if_mul(sx,if_scale(gamma->scales[0])),denom);for(unsigned i=0;i<n;i++)r->work[i]=if_mul(if_make((int64_t)x[i]*gamma->gamma[i],0),factor);int_pack16(out,os,r->work,n,&r->stats);}
void int_rope(IRuntime *r,int16_t *x,IScale *s){const int16_t *table=r->model->rope+(size_t)r->pos*96;IScale xs=*s;for(unsigned i=0;i<48;i++){int64_t a=x[i],b=x[i+48],co=table[2*i],si=table[2*i+1];IFixed factor=if_scale(xs);factor.e-=15;r->work[i]=if_mul(if_make(a*co-b*si,0),factor);r->work[i+48]=if_mul(if_make(b*co+a*si,0),factor);}int_pack16(x,s,r->work,96,&r->stats);}
static uint32_t exp_value(IRuntime *r,int64_t x){if(x<-(INT64_C(16)<<16)){r->stats.exp_outside++;return 0;}if(x>=0)return UINT32_C(1)<<31;uint64_t t=(uint64_t)(-x);unsigned i=(unsigned)(t>>8),f=(unsigned)(t&255);const uint32_t *lut=r->model->exp_lut;if(i>=4096)return lut[4096];return (uint32_t)even_div((uint64_t)lut[i]*(256-f)+(uint64_t)lut[i+1]*f,256);}
/* Per-call stable mergesort, avoiding process-global comparator state. */
static int rem_before(const IRuntime *r,unsigned a,unsigned b){return r->remainders[a]>r->remainders[b]||(r->remainders[a]==r->remainders[b]&&a<b);}
void int_softmax(IRuntime *r,unsigned n){int32_t max=r->scores[0];for(unsigned i=1;i<n;i++)if(r->scores[i]>max)max=r->scores[i];uint64_t sum=0;for(unsigned i=0;i<n;i++){r->remainders[i]=exp_value(r,(int64_t)r->scores[i]-max);sum+=r->remainders[i];}unsigned assigned=0;for(unsigned i=0;i<n;i++){uint64_t v=r->remainders[i]*65535;r->prob[i]=(uint16_t)(v/sum);r->remainders[i]=v%sum;r->order[i]=i;assigned+=r->prob[i];}/* At most n-1 unit corrections; selection keeps stable position ties. */for(unsigned i=0;i<65535-assigned;i++){unsigned best=i;for(unsigned j=i+1;j<n;j++)if(rem_before(r,r->order[j],r->order[best]))best=j;unsigned t=r->order[i];r->order[i]=r->order[best];r->order[best]=t;r->prob[r->order[i]]++;}}
static unsigned sigmoid_value(IRuntime *r,IFixed x){IFixed fixed=x;fixed.e+=16;int64_t q=if_integer(fixed,32,NULL);if(q<-(INT64_C(16)<<16)){r->stats.sig_outside++;return 0;}if(q>(INT64_C(16)<<16)){r->stats.sig_outside++;return 65535;}unsigned t=(unsigned)(q+(INT64_C(16)<<16)),i=t>>8,f=t&255;if(i>=8192)return r->model->sig_lut[8192];return (unsigned)even_div((uint64_t)r->model->sig_lut[i]*(256-f)+(uint64_t)r->model->sig_lut[i+1]*f,256);}
void int_swiglu(IRuntime *r){IFixed factor=if_div(if_mul(if_scale(r->gs),if_scale(r->us)),if_make(65535,0));for(unsigned i=0;i<2432;i++){unsigned sig=sigmoid_value(r,if_value(r->g[i],r->gs));int64_t product=(int64_t)r->g[i]*r->u[i]*(int64_t)sig;r->work[i]=if_mul(if_make(product,0),factor);}int_pack16(r->g,&r->gs,r->work,2432,&r->stats);}
void int_residual(IRuntime *r,int16_t *out,IScale *os,const int16_t *a,IScale as,const int16_t *b,IScale bs,unsigned n){for(unsigned i=0;i<n;i++)r->work[i]=if_add(if_value(a[i],as),if_value(b[i],bs));int_pack16(out,os,r->work,n,&r->stats);}
